import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SDL","description":"","frontmatter":{"title":"SDL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sdl-lifecycle.md","filePath":"cs/sdl-lifecycle.md","lastUpdated":1789023840000}'),h={name:"cs/sdl-lifecycle.md"};function E(_,a,f,m,u,A){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="sdl" tabindex="-1">SDL <a class="header-anchor" href="#sdl" aria-label="Permalink to &quot;SDL&quot;">​</a></h1><div class="epigraph"><p>安全开发生命周期把威胁建模、设计审查、工具门禁、事件响应写进版本列车。它是过程控制，不是一次扫描。微软 SDL 是公开的工程模板之一。</p><footer>—— Howard and Lipner, *The Security Development Lifecycle*；Microsoft SDL；对照 McGraw</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/tcb-minimization">TCB</a>要可审。缺口是<strong>组织如何持续生产较小 TCB</strong>：门禁。本课 SDL。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发布火车无安全活动则回归。缺口：需求阶段威胁模型、编译器与 sanitizer 门禁、依赖审查、就绪检查。</p><h3 id="度量" tabindex="-1">度量 <a class="header-anchor" href="#度量" aria-label="Permalink to &quot;度量&quot;">​</a></h3><p>漏洞密度与修复时间接风险课，不是 KPI 虚荣。</p><p><span class="marginnote">Howard–Lipner。seL4 下一课是另一极端：形式验证微内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按阶段插已讲活动：fuzz、审查、SBOM。下一课 seL4 封课程。</p>',12)),(e(),n(p,null,{default:r(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E9%9C%80%E6%B1%82%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20DES%5B%22%E8%AE%BE%E8%AE%A1%E5%AE%A1%E6%9F%A5%22%5D%0A%20%20DES%20--%3E%20IMP%5B%22%E5%B7%A5%E5%85%B7%E9%97%A8%E7%A6%81%22%5D%0A%20%20IMP%20--%3E%20REL%5B%22%E5%B0%B1%E7%BB%AA%E4%B8%8E%E5%93%8D%E5%BA%94%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过程把课程合同变成列车上的门。形式验证下一课把微内核收到可机检证明。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 SDL 写成官僚表格。seL4 形式验证下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCB 要过程才能保持小。</li><li>威胁模型到门禁到响应是闭环。</li><li>工具是门，不是一次性扫描。</li><li>下一课 seL4 形式验证。</li><li>出处：Howard and Lipner；Microsoft SDL；McGraw。</li></ul>',8))])}const D=l(h,[["render",E]]);export{B as __pageData,D as default};
